class Solution {
public:
    int minDominoRotations(vector<int>& tops, vector<int>& bottoms) {
        int n = tops.size();
        int ans = INT_MAX;
        int c1 = tops[0], c2 = bottoms[0];
        for (int v : {c1, c2}) {
            int topRot = 0, botRot = 0;
            bool ok = true;
            for (int i = 0; i < n; i++) {
                if (tops[i] != v && bottoms[i] != v) {
                    ok = false;
                    break;
                }
                if (tops[i] != v) topRot++;
                if (bottoms[i] != v) botRot++;
            }
            if (ok) {
                ans = min(ans, min(topRot, botRot));
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};
